// --- file: mathUtils.js ---
const add = (a, b) => a + b;
const subtract = (a, b) => a - b;

// Exporting a single object containing multiple functions
module.exports = {
  add,
  subtract
};

// --- file: app.js ---
// Importing the module
const math = require('./mathUtils.js'); // .js extension is optional in CommonJS

console.log("Add:", math.add(5, 10));
console.log("Subtract:", math.subtract(20, 5));

